package com.turboio.addon;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.Toast;
import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Android document picker over a bounded, hash-verified streaming ZIP draft. */
public final class MaterialAudioExport extends Fragment {
 private static final int REQUEST=14533;private static final ExecutorService IO=Executors.newSingleThreadExecutor();private static final Handler MAIN=new Handler(Looper.getMainLooper());private static final AtomicBoolean preparing=new AtomicBoolean();
 private boolean launched,finished,working;private String pendingUri,completion;private int persistedFlags;
 static String label(String error){if(error.equals("OFFICIAL_ACCOUNT_CHANGED"))return "账号已变化，请重新打开资料";if(error.equals("AUDIO_EXPORT_NO_FRAMES"))return "这份记录没有可导出的音频，原始数据已保留";if(error.equals("AUDIO_EXPORT_SOURCE_PENDING"))return "原音已保存，正在等待对应的智记记录";if(error.equals("AUDIO_REMOTE_EMPTY"))return "这条智记没有仍在保留期内的远程原音";if(error.equals("AUDIO_CONFIG_REQUIRED"))return "请先在原音备份设置中配置独立原音连接";if(error.contains("SCOPE")||error.contains("AUTH")||error.contains("CREDENTIAL")||error.contains("EXPIRED"))return "原音读取授权不可用或已到期，请检查原音备份设置";if(error.equals("AUDIO_CONNECTION_CHANGED"))return "原音连接已变化，请重新导出";if(error.equals("AUDIO_REMOTE_TIMEOUT"))return "本次下载未完成，再次导出可继续下载";if(error.contains("BUSY"))return "正在准备另一份原音，请稍后重试";if(error.contains("BUDGET")||error.contains("DISK_FULL")||error.contains("CAPACITY"))return "原音或缓存超过本次导出上限，请检查可用空间";if(error.contains("UNSUPPORTED")||error.contains("DECODE"))return "这段原音暂不能导出，原始数据已保留";return "原音尚未导出，请稍后重试";}
 private static AudioConfig remoteConfig(Context app,String account,String fingerprint)throws Exception{LifelogAudioRuntime.account(account);AudioConfig config=new AudioSettings(app).load();if(config==null)throw new IOException("AUDIO_CONFIG_REQUIRED");if(!account.equals(config.account))throw new IOException("OFFICIAL_ACCOUNT_CHANGED");if(fingerprint!=null&&!fingerprint.equals(config.fingerprint()))throw new IOException("AUDIO_CONNECTION_CHANGED");if(config.connection.expiresAt<=System.currentTimeMillis())throw new IOException("AUDIO_CREDENTIAL_EXPIRED");LifelogAudioRuntime.account(account);return config;}
 private static LifelogAudioArchive.Guard remoteGuard(Context app,String account,String fingerprint)throws Exception{AudioConfig initial=remoteConfig(app,account,fingerprint);long deadline=System.nanoTime()+TimeUnit.MINUTES.toNanos(2);long[] checked={0};return ()->{long now=System.nanoTime();if(now>deadline)throw new IOException("AUDIO_REMOTE_TIMEOUT");LifelogAudioRuntime.account(account);if(initial.connection.expiresAt<=System.currentTimeMillis())throw new IOException("AUDIO_CREDENTIAL_EXPIRED");if(now-checked[0]>=TimeUnit.MILLISECONDS.toNanos(250)){try{remoteConfig(app,account,fingerprint);checked[0]=now;}catch(IOException failure){throw failure;}catch(Exception failure){throw new IOException("AUDIO_CONFIG_UNAVAILABLE");}}};}
 private static MaterialApi.Transport remoteHttp(Context app,AudioConfig expected){AudioReadHttp http=new AudioReadHttp(expected.connection);return new MaterialApi.Transport(){private void current()throws IOException{try{remoteConfig(app,expected.account,expected.fingerprint());}catch(IOException failure){throw failure;}catch(Exception failure){throw new IOException("AUDIO_CONFIG_UNAVAILABLE");}}public MaterialApi.Response exchange(String path,byte[] body)throws IOException{current();MaterialApi.Response result=http.exchange(path,body);current();return result;}public void cancel(){http.cancel();}};}
 static void saveRemote(Activity activity,String account,MaterialCatalog.Entry entry){if(!preparing.compareAndSet(false,true)){Toast.makeText(activity,"正在准备原音…",Toast.LENGTH_SHORT).show();return;}Context app=activity.getApplicationContext();WeakReference<Activity> host=new WeakReference<>(activity);Toast.makeText(activity,"正在下载并核验远程原音，完成后选择保存位置…",Toast.LENGTH_LONG).show();IO.execute(()->{LifelogAudioExport.Draft draft=null;MaterialApi.Transport http=null;try{AudioConfig config=remoteConfig(app,account,null);LifelogAudioArchive.Guard guard=remoteGuard(app,account,config.fingerprint());http=remoteHttp(app,config);draft=AudioRemoteExport.prepare(app.getCacheDir(),config,entry.id,java.util.Collections.emptyList(),http,Host107OpusFileDecoder::new,guard,System::currentTimeMillis);showPicker(host,app,draft,true,config.fingerprint());}catch(Exception failed){if(draft!=null)cleanup(app,draft.id);notice(host,label(failed.getMessage()==null?"":failed.getMessage()));}finally{if(http!=null)http.cancel();preparing.set(false);}});}
 private static void showPicker(WeakReference<Activity> host,Context app,LifelogAudioExport.Draft ready,boolean remote,String fingerprint){MAIN.post(()->{Activity a=host.get();if(a==null||a.isFinishing()||a.isDestroyed()){IO.execute(()->cleanup(app,ready.id));return;}MaterialAudioExport picker=new MaterialAudioExport();Bundle args=new Bundle();args.putString("id",ready.id);args.putString("account",ready.account);args.putBoolean("remote",remote);if(remote)args.putString("fingerprint",fingerprint);picker.setArguments(args);try{a.getFragmentManager().beginTransaction().add(picker,"io-audio-export-"+ready.id).commit();}catch(RuntimeException stopped){IO.execute(()->cleanup(app,ready.id));notice(host,"页面已切换，请重新选择导出");}});}
 static void save(Activity activity,String account,MaterialCatalog.Entry entry){if(!preparing.compareAndSet(false,true)){Toast.makeText(activity,"正在准备原音…",Toast.LENGTH_SHORT).show();return;}Context app=activity.getApplicationContext();WeakReference<Activity> host=new WeakReference<>(activity);Toast.makeText(activity,"正在整理已保存的原音片段…",Toast.LENGTH_SHORT).show();
  LifelogAudioRuntime.freeze(account,entry.id,(sessions,archives,error)->{if(!error.isEmpty()){preparing.set(false);notice(host,label(error));return;}IO.execute(()->{LifelogAudioExport.Draft draft=null;try{draft=LifelogAudioExport.prepare(app.getFilesDir(),app.getCacheDir(),account,entry.id,sessions,archives,Host107OpusFileDecoder::new,()->LifelogAudioRuntime.account(account),System.currentTimeMillis());}catch(Exception failed){notice(host,label(failed.getMessage()==null?"":failed.getMessage()));}finally{preparing.set(false);}if(draft==null)return;LifelogAudioExport.Draft ready=draft;MAIN.post(()->{Activity a=host.get();if(a==null||a.isFinishing()||a.isDestroyed()){IO.execute(()->cleanup(app,ready.id));return;}MaterialAudioExport picker=new MaterialAudioExport();Bundle args=new Bundle();args.putString("id",ready.id);args.putString("account",ready.account);picker.setArguments(args);try{a.getFragmentManager().beginTransaction().add(picker,"io-audio-export-"+ready.id).commit();}catch(RuntimeException stopped){IO.execute(()->cleanup(app,ready.id));notice(host,"页面已切换，请重新选择导出");}});});});
 }
 @Override public void onCreate(Bundle state){super.onCreate(state);setRetainInstance(true);if(state!=null){launched=state.getBoolean("launched");finished=state.getBoolean("finished");pendingUri=state.getString("pending_uri");persistedFlags=state.getInt("persisted_flags");completion=state.getString("completion");}}
 @Override public void onSaveInstanceState(Bundle state){state.putBoolean("launched",launched);state.putBoolean("finished",finished);state.putString("pending_uri",pendingUri);state.putInt("persisted_flags",persistedFlags);state.putString("completion",completion);super.onSaveInstanceState(state);}
 @Override public void onActivityCreated(Bundle state){super.onActivityCreated(state);if(finished){deliver();return;}if(getArguments()==null){finish("导出准备已失效，请重新选择导出");return;}if(working)return;if(pendingUri!=null){write(Uri.parse(pendingUri));return;}preparePicker();}
 private static LifelogAudioExport.Draft load(Context app,Bundle args)throws Exception{if(args==null)throw new IOException("AUDIO_EXPORT_DRAFT");String account=args.getString("account");LifelogAudioRuntime.account(account);LifelogAudioExport.Draft draft=LifelogAudioExport.load(app.getCacheDir(),args.getString("id"),account,System.currentTimeMillis());if(args.getBoolean("remote")){AudioConfig config=remoteConfig(app,account,args.getString("fingerprint"));MaterialApi.Transport http=remoteHttp(app,config);try{AudioRemoteExport.verify(app.getCacheDir(),draft,config,http,remoteGuard(app,account,config.fingerprint()),System::currentTimeMillis);}finally{http.cancel();}}return draft;}
 private void preparePicker(){Activity a=getActivity();if(a==null)return;working=true;Context app=a.getApplicationContext();Bundle args=new Bundle(getArguments());IO.execute(()->{LifelogAudioExport.Draft draft=null;try{draft=load(app,args);}catch(Exception ignored){}LifelogAudioExport.Draft ready=draft;MAIN.post(()->{working=false;if(finished||!isAdded())return;if(ready==null){finish("导出准备已失效，请重新选择导出");return;}if(launched)return;launched=true;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,ready.title).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),REQUEST);}catch(RuntimeException failed){finish("没有可用的文件保存位置，请重试");}});});}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=REQUEST||finished||working)return;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){finish(null);return;}Activity a=getActivity();if(a==null){finish("未完成原音保存，请重新导出");return;}pendingUri=data.getData().toString();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((data.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0)try{a.getContentResolver().takePersistableUriPermission(data.getData(),flags);persistedFlags=flags;}catch(RuntimeException ignored){}write(data.getData());}
 private void write(Uri uri){Activity a=getActivity();if(a==null)return;working=true;Context app=a.getApplicationContext();Bundle args=new Bundle(getArguments());int grants=persistedFlags;IO.execute(()->{String message;try{LifelogAudioExport.Draft draft=load(app,args);LifelogAudioRuntime.account(draft.account);try(OutputStream out=app.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("AUDIO_EXPORT_DESTINATION");LifelogAudioExport.copy(draft,out,args.getBoolean("remote")?remoteGuard(app,draft.account,args.getString("fingerprint")):()->LifelogAudioRuntime.account(draft.account));}message="原音片段已保存到所选位置，解压后即可播放";}catch(Exception failed){message="未完整保存，请删除目标文件后重新导出；本次操作未删除来源原音";}cleanup(app,args.getString("id"));if(grants!=0)try{app.getContentResolver().releasePersistableUriPermission(uri,grants);}catch(RuntimeException ignored){}String done=message;MAIN.post(()->{working=false;finished=true;pendingUri=null;persistedFlags=0;completion=done;deliver();});});}
 private void finish(String message){finished=true;completion=message;Activity a=getActivity();Bundle args=getArguments();if(a!=null&&args!=null){Context app=a.getApplicationContext();IO.execute(()->cleanup(app,args.getString("id")));}deliver();}
 private void deliver(){Activity a=getActivity();if(a==null)return;if(completion!=null){Toast.makeText(a,completion,Toast.LENGTH_LONG).show();completion=null;}if(isAdded())getFragmentManager().beginTransaction().remove(this).commitAllowingStateLoss();}
 private static void cleanup(Context app,String id){try{LifelogAudioExport.remove(app.getCacheDir(),id);}catch(Exception ignored){}}
 private static void notice(WeakReference<Activity> host,String message){MAIN.post(()->{Activity a=host.get();if(a!=null&&!a.isFinishing()&&!a.isDestroyed())Toast.makeText(a,message,Toast.LENGTH_LONG).show();});}
}
